function AnimatedCounter({ value, label }: { value: number; label: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  const springValue = useSpring(0, {
    stiffness: 50,
    damping: 20,
    duration: 2000,
  });

  useEffect(() => {
    if (isInView) {
      springValue.set(value);
    }
  }, [isInView, springValue, value]);

  const displayValue = useTransform(springValue, (current) =>
    Math.round(current).toLocaleString()
  );

  return (
    <div ref={ref} className="flex flex-col items-center justify-center p-6 text-center space-y-2">
      <motion.div className="text-4xl md:text-6xl font-bold tracking-tighter text-foreground">
        {displayValue}
      </motion.div>
      <div className="text-sm md:text-base font-medium text-muted-foreground uppercase tracking-widest">{label}</div>
    </div>
  );
}

function Marquee({ children, reverse = false }: { children: React.ReactNode; reverse?: boolean }) {
  return (
    <div className="relative flex w-full overflow-hidden flex-nowrap py-4">
      <div className="absolute inset-y-0 left-0 w-1/4 md:w-1/3 bg-gradient-to-r from-background to-transparent z-10 pointer-events-none"></div>
      <div className="absolute inset-y-0 right-0 w-1/4 md:w-1/3 bg-gradient-to-l from-background to-transparent z-10 pointer-events-none"></div>

      <div className={`flex w-max animate-marquee ${reverse ? 'reverse' : ''}`}>
        <div className="flex gap-8 px-4 items-center">{children}</div>
        <div className="flex gap-8 px-4 items-center">{children}</div>
        <div className="flex gap-8 px-4 items-center">{children}</div>
      </div>
    </div>
  );
}

